// Build the low-stock alert email from the store's inventory.low event.
// The store decides the threshold (Settings → Inventory) and fires once per crossing.
const p = $input.first().json.body ?? $input.first().json;
const d = p.data || {};
const available = Number(p.current_available ?? d.available);
const threshold = Number(d.threshold ?? 5);
const title = (d.product_title || 'A product') + (d.variant_title && d.variant_title !== 'Default' ? ' — ' + d.variant_title : '');

const reorder = available <= 0
  ? 'OUT OF STOCK — reorder immediately.'
  : `Suggest reordering soon. At current pace this is roughly ${available} sales from selling out.`;

const html =
  `<!DOCTYPE html><html><body style="margin:0;padding:0;background-color:#f8f5f0;">` +
  `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f8f5f0;"><tr><td align="center" style="padding:32px 16px;">` +
  `<table role="presentation" cellpadding="0" cellspacing="0" style="max-width:560px;width:100%;">` +
  `<tr><td style="padding:40px 8px 24px;text-align:center;">` +
  `<div style="font-family:'Playfair Display',Georgia,serif;font-size:22px;letter-spacing:.18em;color:#232f48;">AALMARAM</div>` +
  `<div style="width:48px;height:2px;background:#a4422c;margin:16px auto 0;font-size:0;">&nbsp;</div>` +
  `</td></tr>` +
  `<tr><td style="font-family:'Nunito',Helvetica,Arial,sans-serif;font-size:16px;line-height:1.7;color:#232f48;padding:8px;">` +
  `<p style="font-size:13px;letter-spacing:.2em;color:#a4422c;">LOW INVENTORY ALERT</p>` +
  `<p><strong>${title}</strong></p>` +
  `<p>Current stock: <strong>${available}</strong> (threshold: ${threshold})</p>` +
  `<p>${reorder}</p>` +
  `</td></tr></table></td></tr></table></body></html>`;

return [{
  json: {
    subject: `Low stock: ${title} — ${available} left`,
    html
  }
}];
